function cliff(x,z,scale){let obstacle={x,z,r:scale*.7};obstacles.push(obstacle);let g=new T.Group();g.position.set(x,-5,z);obstacle.group=g;scene.add(g);for(let i=0;i<8;i++){let ang=i*2.4,r=i?scale*.45:0;let m=mesh(new T.IcosahedronGeometry(scale*(.4+Math.random()*.2),1),rock,g,Math.cos(ang)*r,scale*.5,Math.sin(ang)*r);m.rotation.y=i;m.scale.set(1,2.5+Math.random()*2,1);m.rotation.z=(Math.random()-.5)*.25}return g}
