const FX_BASES=['../assets/','./assets/'].map(b=>new URL(b,import.meta.url).href),FX={},FX_LAST={};let FX_CTX=null,FX_BED=null;const FX_MUTED=()=>!!(!soundOn),fxVary=(a=.06)=>1-a+Math.random()*a*2;
function fxLoad(ctx,n,i=0){if(i>=FX_BASES.length){FX[n]=false;return}fetch(FX_BASES[i]+n).then(r=>{if(!r.ok)throw 0;return r.arrayBuffer()}).then(b=>ctx.decodeAudioData(b)).then(b=>FX[n]=b).catch(()=>fxLoad(ctx,n,i+1))}
function fxInit(ctx){if(FX_CTX||!ctx)return;FX_CTX=ctx;for(const n of ['sfx_cutlass.ogg','sfx_gold.ogg','sfx_sea_wind.ogg','sfx_splash.ogg'])fxLoad(ctx,n);fxBed('sfx_sea_wind.ogg');setInterval(()=>{if(FX_BED)FX_BED.gain.value=FX_MUTED()?0:0.16},250);}
function fx(n,vol=1,rate=1,gap=0){if(!FX_CTX||!FX[n]||FX_MUTED())return false;const now=performance.now();if(gap&&now-(FX_LAST[n]||0)<gap)return true;FX_LAST[n]=now;const s=FX_CTX.createBufferSource(),g=FX_CTX.createGain();s.buffer=FX[n];s.playbackRate.value=rate;g.gain.value=vol;s.connect(g).connect(audioCtx.destination);s.start();return true}
// sfx_sea_wind.ogg: the file swells in over its first half second and fades out after ~2.1 s (then silence), so the bed keeps overlapping fresh takes of its steady 0.5-2.1 s stretch at slightly different pitch and level. Continuous, no audible loop point, and it follows the sound switch.
